            List<string> keys = new List<string>();
            T current = element;
            while (current != null) {
                keys.Add(current.Key);
                IOwner owner = current.GetOwner();
                if (owner == root) {
                    break;
                }
                current = owner as T;
            }
            keys.Reverse();
            return keys.ToArray();
